"""Policy Engine: working days and available balance (data-driven per leave type)."""
from dataclasses import dataclass
from datetime import timedelta


@dataclass(frozen=True)
class LeavePolicy:
    leave_type: str
    annual_entitlement: float
    max_carry_over: float = 0.0


def working_days(start, end, holidays=frozenset()):
    """Count Monday-Friday days from start to end inclusive, excluding holidays."""
    if end < start:
        raise ValueError("end date is before start date")
    days, current = 0, start
    while current <= end:
        if current.weekday() < 5 and current not in holidays:
            days += 1
        current += timedelta(days=1)
    return days


def available_balance(policy, carried_over, approved_days, pending_days):
    """Entitlement + capped carry-over - approved - pending (US-3-AC1)."""
    carry = min(carried_over, policy.max_carry_over)
    return policy.annual_entitlement + carry - approved_days - pending_days

"""Leave Service + Approval Workflow (in-memory repository for this slice)."""
from dataclasses import dataclass, field
from datetime import datetime, timezone
from itertools import count

from leave.policy import available_balance, working_days

PENDING, APPROVED, REJECTED = "PENDING", "APPROVED", "REJECTED"


class LeaveError(ValueError):
    pass


@dataclass
class LeaveRequest:
    id: int
    employee_id: str
    leave_type: str
    start: object
    end: object
    days: int
    status: str = PENDING
    rejection_reason: str = ""


@dataclass
class LeaveService:
    policies: dict
    managers: dict  # employee_id -> manager_id, supplied by the Directory Adapter
    holidays: frozenset = frozenset()
    carried_over: dict = field(default_factory=dict)
    requests: dict = field(default_factory=dict)
    audit: list = field(default_factory=list)
    _ids: object = field(default_factory=lambda: count(1))

    def _days(self, employee_id, leave_type, status):
        return sum(r.days for r in self.requests.values()
                   if r.employee_id == employee_id and r.leave_type == leave_type
                   and r.status == status)

    def balance(self, employee_id, leave_type):
        return available_balance(
            self.policies[leave_type],
            self.carried_over.get((employee_id, leave_type), 0.0),
            self._days(employee_id, leave_type, APPROVED),
            self._days(employee_id, leave_type, PENDING),
        )

    def submit(self, employee_id, leave_type, start, end):
        if leave_type not in self.policies:
            raise LeaveError(f"unknown leave type {leave_type}")
        days = working_days(start, end, self.holidays)
        for r in self.requests.values():
            if (r.employee_id == employee_id and r.status in (PENDING, APPROVED)
                    and r.start <= end and start <= r.end):
                raise LeaveError(f"overlaps request {r.id}")
        available = self.balance(employee_id, leave_type)
        if days > available:
            raise LeaveError(f"insufficient balance: requested {days}, available {available}")
        request = LeaveRequest(next(self._ids), employee_id, leave_type, start, end, days)
        self.requests[request.id] = request
        self._record("create", employee_id, request, None)
        return request

    def approve(self, manager_id, request_id):
        request = self._pending_for(manager_id, request_id)
        previous, request.status = request.status, APPROVED
        self._record("approve", manager_id, request, previous)
        return request

    def reject(self, manager_id, request_id, reason):
        if not reason or not reason.strip():
            raise LeaveError("a rejection reason is required")
        request = self._pending_for(manager_id, request_id)
        previous, request.status, request.rejection_reason = request.status, REJECTED, reason
        self._record("reject", manager_id, request, previous)
        return request

    def _pending_for(self, manager_id, request_id):
        request = self.requests[request_id]
        if self.managers.get(request.employee_id) != manager_id:
            raise LeaveError("only the employee's direct manager can decide this request")
        if request.status != PENDING:
            raise LeaveError(f"request {request_id} is already {request.status}")
        return request

    def _record(self, action, actor, request, previous):
        self.audit.append({
            "action": action, "actor": actor, "request_id": request.id,
            "previous_status": previous, "new_status": request.status,
            "at": datetime.now(timezone.utc).isoformat(),
        })
